function initIntro() {
const dismissIntro = () => {
if (introScreen) introScreen.classList.add('hidden');
};
setTimeout(dismissIntro, 1200);
window.addEventListener('scroll', dismissIntro, { once: true });
window.addEventListener('click', dismissIntro, { once: true });
window.addEventListener('touchstart', dismissIntro, { once: true });
}

let targetVideoTime = 0;
let isVideoReady = false;
const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (heroVideo) {
heroVideo.addEventListener('loadedmetadata', () => {
isVideoReady = true;
heroVideo.pause();
});
}
function onHeroScroll() {
const rect = heroTrack.getBoundingClientRect();
const maxScroll = heroTrack.offsetHeight - window.innerHeight;
const scrolled = -rect.top;
const progress = Math.min(Math.max(scrolled / maxScroll, 0), 1);
targetVideoTime = progress * VIDEO_DURATION;
if (scrolled >= maxScroll - 60) {
mainHeader.classList.remove('transparent');
mainHeader.classList.add('scrolled');
} else {
mainHeader.classList.add('transparent');
mainHeader.classList.remove('scrolled');
}
if (timelineProgress) {
timelineProgress.style.height = `${progress * 100}%`;
}
const welcomeOverlay = document.getElementById('hero-welcome-overlay');
if (welcomeOverlay) {
if (progress >= 0.76) {
welcomeOverlay.classList.add('visible');
} else {
welcomeOverlay.classList.remove('visible');
}
}
startHeroScrubbing();
}
window.addEventListener('scroll', onHeroScroll, { passive: true });
let isScrubbingActive = false;
function startHeroScrubbing() {
if (!isScrubbingActive && isVideoReady && !prefersReducedMotion) {
isScrubbingActive = true;
requestAnimationFrame(updateVideoScrub);
}
}
function updateVideoScrub() {
if (isVideoReady && !prefersReducedMotion && heroVideo) {
const diff = targetVideoTime - heroVideo.currentTime;
if (Math.abs(diff) > 0.005) {
heroVideo.currentTime += diff * 0.06;
requestAnimationFrame(updateVideoScrub);
return;
}
}
isScrubbingActive = false;
}

