function initStoryDressSlider() {
const track = document.getElementById('story-slider-track');
const box = document.getElementById('story-slider-box');
const counter = document.getElementById('story-slide-counter');
const dots = document.querySelectorAll('#story-slider-dots .slider-dot');
const progressBar = document.getElementById('story-progress-bar');
if (!track || !box) return;
const slides = track.querySelectorAll('.story-slide');
const totalSlides = slides.length;
if (totalSlides === 0) return;
let currentIndex = 0;
let intervalId = null;
let progressIntervalId = null;
const slideDuration = 2000; // 2.0s interval as requested
let elapsed = 0;
function updateSlide(index) {
currentIndex = (index + totalSlides) % totalSlides;
track.style.transform = `translateX(-${currentIndex * 100}%)`;
if (counter) {
counter.textContent = `${String(currentIndex + 1).padStart(2, '0')} / ${String(totalSlides).padStart(2, '0')}`;
}
dots.forEach((dot, idx) => {
dot.classList.toggle('active', idx === currentIndex);
});
elapsed = 0;
if (progressBar) progressBar.style.width = '0%';
}
function startTimer() {
stopTimer();
elapsed = 0;
progressIntervalId = setInterval(() => {
elapsed += 50;
const pct = Math.min((elapsed / slideDuration) * 100, 100);
if (progressBar) progressBar.style.width = pct + '%';
}, 50);
intervalId = setInterval(() => {
updateSlide(currentIndex + 1);
}, slideDuration);
}
function stopTimer() {
if (intervalId) clearInterval(intervalId);
if (progressIntervalId) clearInterval(progressIntervalId);
intervalId = null;
progressIntervalId = null;
}
dots.forEach(dot => {
dot.addEventListener('click', (e) => {
const targetIndex = parseInt(e.target.dataset.slide, 10);
if (!isNaN(targetIndex)) {
updateSlide(targetIndex);
startTimer();
}
});
});
box.addEventListener('mouseenter', stopTimer);
box.addEventListener('mouseleave', startTimer);
updateSlide(0);
startTimer();
}
function initSocialReels() {
const cards = document.querySelectorAll('.insta-tile-video-card');
if (cards.length === 0) return;
const reelItems = [];
cards.forEach(card => {
const video = card.querySelector('.social-reel-video');
const btn = card.querySelector('.social-audio-btn');
const panel = card.querySelector('.social-volume-panel');
const slider = card.querySelector('.social-volume-slider');
const pct = card.querySelector('.social-volume-pct');
const toast = card.querySelector('.social-audio-toast');
if (!video) return;
reelItems.push({ video, btn, panel, slider, pct, toast });
video.muted = true;
video.volume = 0.8;
video.play().catch(() => {});
function showToast(text) {
if (!toast) return;
toast.textContent = text;
toast.classList.add('active');
clearTimeout(toast._timer);
toast._timer = setTimeout(() => toast.classList.remove('active'), 1800);
}
function updateBtn(isMuted) {
if (!btn) return;
if (isMuted) {
btn.classList.add('is-muted');
btn.classList.remove('is-unmuted');
btn.setAttribute('title', 'Tap to unmute & adjust volume');
} else {
btn.classList.remove('is-muted');
btn.classList.add('is-unmuted');
btn.setAttribute('title', 'Tap to mute');
}
}
function toggleMuteAndVolume(showPanel = true) {
const willMute = !video.muted;
if (willMute) {
video.muted = true;
updateBtn(true);
if (panel) panel.classList.remove('active');
showToast('Muted 🔇');
} else {
reelItems.forEach(item => {
if (item.video !== video) {
item.video.muted = true;
if (item.btn) {
item.btn.classList.add('is-muted');
item.btn.classList.remove('is-unmuted');
}
if (item.panel) item.panel.classList.remove('active');
}
});
video.muted = false;
video.volume = slider ? parseFloat(slider.value) : 0.8;
video.play().catch(() => {});
updateBtn(false);
if (showPanel && panel) {
panel.classList.add('active');
clearTimeout(panel._hideTimer);
panel._hideTimer = setTimeout(() => {
panel.classList.remove('active');
}, 4000);
}
showToast('Volume Active 🔊');
}
}
if (btn) {
btn.addEventListener('click', (e) => {
e.preventDefault();
e.stopPropagation();
if (panel && panel.classList.contains('active')) {
toggleMuteAndVolume(false);
} else {
toggleMuteAndVolume(true);
}
});
}
if (slider) {
slider.addEventListener('input', (e) => {
e.stopPropagation();
const val = parseFloat(e.target.value);
video.volume = val;
if (pct) pct.textContent = `${Math.round(val * 100)}%`;
if (val === 0) {
video.muted = true;
updateBtn(true);
} else {
video.muted = false;
updateBtn(false);
}
if (panel) {
clearTimeout(panel._hideTimer);
panel._hideTimer = setTimeout(() => {
panel.classList.remove('active');
}, 3500);
}
});
slider.addEventListener('click', (e) => {
e.stopPropagation();
});
}
if (panel) {
panel.addEventListener('click', (e) => e.stopPropagation());
}
card.addEventListener('click', (e) => {
if (e.target.closest('.social-insta-btn') || e.target.closest('a')) return;
if (e.target.closest('.social-sound-control-group')) return;
toggleMuteAndVolume(true);
});
card.addEventListener('mouseleave', () => {
if (panel) panel.classList.remove('active');
});
});
}
